create or replace package body billing_api as
  procedure pay(p_bill_id in number, p_amount in number) is
    l_bill_amount number;
    l_paid_amount number;
  begin
    insert into bill_payments (bill_id, amount) values (p_bill_id, p_amount);

    select amount into l_bill_amount from bills where bill_id = p_bill_id;
    select nvl(sum(amount), 0) into l_paid_amount from bill_payments where bill_id = p_bill_id;

    if l_paid_amount >= l_bill_amount then
      update bills set status = 'PAID' where bill_id = p_bill_id;
    else
      update bills set status = 'PARTIAL' where bill_id = p_bill_id;
    end if;
  end pay;
end billing_api;
